from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'evs','this-world-of-things','This World of Things',
 ('Khushi looks around her classroom','Khushi reaches school early, and the sunlight makes the classroom bright and beautiful. She draws what she sees and asks herself where all these things come from, who made them and what they are made of. We help her find out about materials such as wood, metal and glass, and learn to group things as solid, liquid or gas, and as natural or artificial.'),
 [('What things are made of',['The table, chair and door are made of wood, which comes from trees. The hinges, nails and latches of the door are made of metal.','Metals are taken from rocks called ore that are dug out from inside the Earth. Common metals are iron, copper, aluminium, gold and silver. Mercury, the metal in a thermometer, is a liquid.','An alloy is a mixture of metals. Steel, brass and bronze are alloys.','Windowpanes and bulbs are made of glass, which is mostly made of sand. Electric switches are made of plastic.','A material is the stuff that a thing is made of. Different things can be made of the same material, and one thing can have more than one material.']),
  ('Transparent, translucent and opaque',['Khushi could see a tree through the glass window pane, without noticing the glass.','Things that we can see through clearly are transparent, and most glass is transparent.','Things that we cannot see through at all are opaque. Wood is opaque.','Things that let some light through but not a clear picture are translucent. A lamp shade made of paper is translucent.','Looking at a white paper through thin coloured plastic or glass can make it look the colour of that plastic. We should never look at the sun directly, because it harms our eyes.']),
  ('Properties of materials',['Different materials feel and sound different. Metal feels cold and shiny, and it makes a ting sound when we tap it. Wood sounds like thak.','A table cannot be made of fabric because fabric is soft and flexible, and a table has to be hard and rigid. Fabric is good for clothes and curtains because it bends.','Some pairs are odd, such as an umbrella made of paper. Paper tears in the rain.','Materials are chosen for what they can do. Their properties, such as hard, soft, bendy, shiny, rough and smooth, tell us how to use them.']),
  ('Solid, liquid and gas',['Things that do not change their shape are solids, like a stone, a spoon, a bottle, a bag and ice.','Water does not keep its shape. It flows and takes the shape of the cup, so it is a liquid. Ink and honey are also liquids.','Air does not stay in a cup. It floats in and out and spreads everywhere. Air is a gas, and so are smoke and steam.','Some things are confusing, such as sand, a sponge or clay. We have to look at how they behave.']),
  ('Natural and artificial',['Things that exist naturally in nature are called natural, such as a mango tree, a mango, a bird, rocks, water and air. Natural things may be alive or not alive.','Things made by people are artificial, such as clothes, shoes and tables.','Khushi drew a mango tree with a mango on it, so she might have drawn it around June, the time when mangoes ripen.','Plastic, petrol and rubber can be made artificially from petroleum, a liquid found deep underground.'])],
 [('Is a glass window transparent, translucent or opaque? Is wood?',[('We can see clearly through the glass window.','We see the tree outside.'),('So glass is transparent.','Clear see-through material.'),('We cannot see through wood, so wood is opaque.','Wood blocks the light.')]),
  ('Sort these: stone, water, air.',[('A stone has its own shape: it is a solid.','It does not flow.'),('Water flows and takes the shape of the cup: it is a liquid.','It stays in the cup.'),('Air spreads out and is not seen: it is a gas.','It does not stay in a cup.')])],
 ('Explain how we can group things around us in two ways.',['Solid, liquid or gas','Natural or artificial','Name examples of each','Say why you grouped them so'],['All things are artificial','Air is a solid']),
 ['Things are made of materials such as wood, metal, glass and plastic.','We can see through transparent things, partly through translucent ones and not at all through opaque ones.','We choose materials for their properties.','Things can be solids, liquids or gases.','Natural things occur in nature, and artificial things are made by people.'],
 [M('1',1,'Which material is the table made of?','Wood',[('Glass','Windows use glass'),('Metal','Hinges use metal')],'The table and chair are made of wood.'),
  M('2',1,'Where does wood come from?','Trees',[('Rocks','Metals come from rocks'),('Sand','Glass comes from sand')],'We get wood from trees.'),
  M('3',1,'What is glass mostly made of?','Sand',[('Wood','Wood is from trees'),('Iron','Iron is a metal')],'Glass is mostly sand.'),
  M('4',1,'What is a material that we can see through clearly called?','Transparent',[('Opaque','Opaque blocks light'),('Translucent','Translucent lets some light')],'Clear glass is transparent.'),
  M('5',2,'Which is opaque?','Wood',[('Clear glass','Clear glass is transparent'),('Air','Air is transparent')],'Wood blocks the light.'),
  M('6',2,'A paper lampshade is?','Translucent',[('Transparent','You cannot see clearly through it'),('Opaque','It lets light pass')],'It lets some light through.'),
  M('7',2,'Which is a liquid?','Water',[('Stone','A stone is a solid'),('Air','Air is a gas')],'Water flows.'),
  M('8',2,'Which is a gas?','Air',[('Honey','Honey is a liquid'),('Ice','Ice is a solid')],'Air spreads everywhere.'),
  M('9',2,'Which is artificial?','A table',[('A mango tree','It occurs naturally'),('A river','It occurs naturally')],'A table is made by people.'),
  F('10',2,'Metals come from ore dug from the Earth.',True,'Ore is dug from inside the Earth.'),
  M('11',3,'Why is a table not made of fabric?','Fabric is soft and bends',[('Fabric is expensive','The reason is the property'),('Fabric is rare','The reason is the property')],'A table must be hard and rigid.'),
  F('12',3,'We may look at the sun directly through glass.',False,'Never look at the sun directly.')],
 keep=['transparent','opaque','translucent','solid','liquid','gas'])
